export interface ValidationReport {
  version: string;
  model: string;
  model_name: string;
  product_version: string;
  skill: {
    levels: string[];
    level_names: Record<string, string>;
    test: string;
    primary_metric: string;
    primary: Record<string, { primary_kge: number; logkge_admin1: number | null }>;
    by_scale: Record<"cell_r5" | "admin1" | "country" | "biome", Record<string, ScaleSkill>>;
    by_biome: Array<{ biome_id: number; biome_name: string; n_months: number; modis_total: number } & Record<string, unknown>>;
  };
  holdout_2020: {
    test: string;
    levels: Record<string, { primary_kge: number; bias_pct: number; admin1_r2: number; country_r2: number; biome_r2: number }>;
    excluding_aqua_outage: { note: string } & Record<string, { primary: number; bias_pct: number } | string>;
    coverage90_admin1: number;
  };
  seamlessness: Array<{ region: string; breakpoint: string; series: string; p_mw: number | null; step_pct: number | null; p_pettitt: number | null; artifact_pp: number | null }>;
  seam_summary: Record<string, { median_abs_artifact_pp: number; n_units: number }>;
  turing: Record<string, { accuracy: number; ci95?: number[]; n?: number; seeds?: number[] } | string>;
  calendar_agreement: Record<string, { kappa: number; exact: number; within_one: number }>;
  coverage90: Record<string, number>;
  limitations: string[];
}

